const t5_root_profile_t *T5RootProfile(const char *clip)
{
    if (!clip) return 0;
    for (unsigned i = 0; i < sizeof(s_profiles) / sizeof(s_profiles[0]); ++i)
        if (!strcmp(s_profiles[i].clip, clip)) return &s_profiles[i];
    return 0;
}

float T5RootTravel(const t5_root_profile_t *p, float t)
{
    if (t <= 0.0f) return 0.0f;
    if (t >= 1.0f) return p->cumulative[T5_ROOT_STEPS];
    float x = t * T5_ROOT_STEPS;
    unsigned i = (unsigned)x;
    float f = x - (float)i;
    return p->cumulative[i] + (p->cumulative[i + 1] - p->cumulative[i]) * f;
}
